INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (100911, 0, "疼く……疼くぞ！\n我が魔眼が新たなる年を祝えと……！", 8, 0, 11, 0, 0, 311006, 311, 0.5);
