INSERT INTO `v1_bc9c943d6415223830b63552eeccee9020d029dd2284487e9efdd8abb9936985` VALUES (103731, 0, "クリスティーナ！\nあなたはいったいどの面下げて\n私たちの前に……", 8, 0, 11, 1, 0, 506013, 506, 0.5);
